// Why Code: Extract From File can't read a form-encoded body kept as binary, and the signature needs those exact bytes.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers || {};
const ts = h['x-slack-request-timestamp'] || '';
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || '';
let p = {};
try { p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' '))); } catch (e) { p = {}; }
return [{ json: {
  raw, ts, signature: h['x-slack-signature'] || '', base: `v0:${ts}:${raw}`,
  fresh: Math.abs(Date.now() / 1000 - Number(ts)) <= 300,
  type: p.type || '', action_id: p.actions?.[0]?.action_id || '', callback_id: p.view?.callback_id || p.callback_id || '',
  channel_id: p.channel?.id || p.container?.channel_id || '', channel_name: p.channel?.name || ''
} }];

// Why Code: the route is a longest-prefix match over three lists, which Switch can't express without one output per workflow.
const t = $('Read the tap').first().json;
const s = $('Router settings').first().json;
const r = s.routes || {};
const signed = t.fresh && ('v0=' + $input.first().json.sig) === t.signature;
if (!signed) return [{ json: { ok: false, status: 401, reason: 'bad or stale signature' } }];
const starts = (v, list) => (list || []).find(x => v && v.startsWith(x.prefix));
let hit = null;
if (t.type === 'block_actions') {
  if ((r.ignore_actions || []).some(a => t.action_id.startsWith(a))) return [{ json: { ok: false, status: 200, reason: 'link button, nothing to do' } }];
  hit = starts(t.action_id, r.action_prefixes);
} else if (t.callback_id) {
  hit = starts(t.callback_id, r.callback_ids);
}
if (!hit && (t.channel_id || t.channel_name)) {
  hit = (r.channels || []).find(c => c.channel === t.channel_id || c.channel === '#' + t.channel_name || c.channel === t.channel_name) || null;
}
if (!hit) return [{ json: { ok: false, status: 200, reason: `no route for ${t.type} ${t.action_id || t.callback_id}` } }];
return [{ json: { ok: true, path: hit.path, workflow: hit.workflow, url: s.internal_url.replace(/\/$/, '') + '/webhook/' + hit.path } }];
